// What this run tagged.
const rows = $input.all().map(i => i.json);
const by = (k) => rows.reduce((a, r) => { const v = r[k] || 'none'; a[v] = (a[v] || 0) + 1; return a; }, {});
return [{ json: { tagged: rows.length, needs_review: rows.filter(r => r.needs_review).length,
  confidence: by('tag_confidence'), main_sector: by('main_sector'),
  examples: rows.slice(0, 15).map(r => r.name + ': ' + (r.main_sector || '?') + ' / ' + (r.company_type || '?') + ' / ' + (r.size_band || '?')) } }];

// For each company: read its job board, keep the UK jobs, and build the tagging prompt.
const sleep = ms => new Promise(r => setTimeout(r, ms));
const helpers = this.helpers;
const get = url => helpers.httpRequest({ method: 'GET', url, json: true, returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 });

const UK_WORDS = /\b(united kingdom|uk|u\.k\.|england|scotland|wales|northern ireland|great britain|britain)\b/i;
const UK_CITIES = /\b(london|manchester|edinburgh|glasgow|leeds|sheffield|liverpool|newcastle upon tyne|nottingham|brighton|bristol|cardiff|belfast|aberdeen|milton keynes|southampton|leicester|coventry|bath|exeter|oxford|cambridge|birmingham|reading)\b/i;
const NOT_UK = /\b(usa|united states|canada|australia|ontario|massachusetts|alabama|new hampshire)\b|,\s*(?!UK\b|GB\b)[A-Z]{2}\b/;
const isUk = s => !!s && (UK_WORDS.test(s) || (UK_CITIES.test(s) && !NOT_UK.test(s)));

const decode = s => String(s || '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
const plain = s => decode(s).replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/\s+/g, ' ').trim();

// The shared lists, from taxonomy_options
const lists = {};
for (const i of $('Get Lists').all()) {
  const { list_name, value, sort_order } = i.json;
  (lists[list_name] = lists[list_name] || []).push({ value, sort_order });
}
const opts = name => (lists[name] || []).sort((a, b) => a.sort_order - b.sort_order).map(o => o.value);

const out = [];
for (const [idx, item] of $input.all().entries()) {
  const c = item.json;
  let boardName = null, boardAbout = '', total = 0;
  const ukJobs = [];
  let fetchNote = '';
  try {
    if (c.source === 'greenhouse') {
      const meta = await get('https://boards-api.greenhouse.io/v1/boards/' + encodeURIComponent(c.slug));
      if (meta.statusCode === 200) { boardName = meta.body.name; boardAbout = plain(meta.body.content); }
      const r = await get('https://boards-api.greenhouse.io/v1/boards/' + encodeURIComponent(c.slug) + '/jobs?content=true');
      const jobs = (r.statusCode === 200 && r.body.jobs) || [];
      total = jobs.length;
      for (const j of jobs) { const loc = j.location && j.location.name; if (isUk(loc)) ukJobs.push({ title: j.title, loc, text: plain(j.content) }); }
    } else if (c.source === 'ashby') {
      const r = await get('https://api.ashbyhq.com/posting-api/job-board/' + encodeURIComponent(c.slug));
      const jobs = ((r.statusCode === 200 && r.body.jobs) || []).filter(j => j.isListed !== false);
      total = jobs.length;
      for (const j of jobs) {
        const country = j.address && j.address.postalAddress && j.address.postalAddress.addressCountry;
        const locs = [j.location, country].concat((j.secondaryLocations || []).map(s => s.location));
        const hit = locs.find(isUk);
        if (hit) ukJobs.push({ title: j.title, loc: j.location, text: j.descriptionPlain || plain(j.descriptionHtml), mode: j.workplaceType });
      }
    } else if (c.source === 'workable') {
      const r = await get('https://apply.workable.com/api/v1/widget/accounts/' + encodeURIComponent(c.slug) + '?details=true');
      if (r.statusCode === 200) {
        boardName = r.body.name; boardAbout = plain(r.body.description);
        const jobs = r.body.jobs || [];
        total = jobs.length;
        for (const j of jobs) {
          const locs = (j.locations || []).concat([{ country: j.country, countryCode: j.countryCode, city: j.city }]);
          const hit = locs.find(l => l && (l.countryCode === 'GB' || isUk(l.country)));
          if (hit) ukJobs.push({ title: j.title, loc: [hit.city, hit.country].filter(Boolean).join(', '), text: plain(j.description), mode: j.telecommuting ? 'Remote' : '' });
        }
      }
    }
  } catch (e) { fetchNote = 'Board could not be read: ' + String(e.message || e).slice(0, 150); }

  const ukLocs = [...new Set(ukJobs.map(j => j.loc).filter(Boolean))].slice(0, 15);
  const titles = [...new Set(ukJobs.map(j => j.title))].slice(0, 12);
  const sample = (ukJobs[0] && ukJobs[0].text || '').slice(0, 3000);

  const prompt = [
    'You are tagging an employer for a UK job search service. Use ONLY the options listed. Answer with JSON only.',
    '',
    'EMPLOYER',
    'Name on job board: ' + (boardName || c.name),
    'Board: ' + c.source + ' / ' + c.slug,
    'Open jobs worldwide: ' + total + '. UK jobs: ' + ukJobs.length,
    'UK job locations: ' + (ukLocs.join('; ') || 'none found'),
    'Sample UK job titles: ' + (titles.join('; ') || 'none'),
    boardAbout ? 'About (from job board): ' + boardAbout.slice(0, 1500) : '',
    sample ? 'One UK job description (often starts with "About us"): ' + sample : '',
    fetchNote,
    '',
    'OPTIONS',
    'sector (main_sector: exactly one; secondary_sectors: 0-2): ' + opts('sector').join(' | '),
    'focus_areas (0-2, only if clearly central to what the company does): ' + opts('focus_area').join(' | '),
    'company_type (one): ' + opts('company_type').join(' | '),
    'size_band (one, total staff): ' + opts('size_band').join(' | '),
    '',
    'RULES',
    '- name: the company\'s usual brand name (fix casing, e.g. "AcmeTech" not "Acmetech").',
    '- description: one plain sentence on what the company does and for whom. No marketing language.',
    '- Use what the job board says first; add your own knowledge of the company only where you are confident it is the same company.',
    '- size_band: best estimate from what you know and the number of open jobs.',
    '- uk_locations: UK towns or cities where it has roles, e.g. ["London"]. hires_remote_uk: true if any UK role is remote.',
    '- confidence: high, medium or low. Use low if the company is unclear or the data is thin.',
    '- review_note: empty, unless no sector fits well; then name the sector you would add.',
    '',
    'Return exactly: {"name":"","description":"","main_sector":"","secondary_sectors":[],"focus_areas":[],"company_type":"","size_band":"","uk_locations":[],"hires_remote_uk":false,"confidence":"","review_note":""}'
  ].filter(l => l !== '').join('\n');

  out.push({ json: { id: c.id, current_name: c.name, uk_locations_found: ukLocs, any_remote: ukJobs.some(j => /remote/i.test(j.mode || '') || /remote/i.test(j.loc || '')), prompt }, pairedItem: { item: idx } });
  await sleep(300);
}
return out;

// Read Claude's JSON, keep only values that are on the lists, and shape the row update.
const src = $('Gather Company Info').item.json;
const allowed = {};
for (const i of $('Get Lists').all()) (allowed[i.json.list_name] = allowed[i.json.list_name] || new Set()).add(i.json.value);
const ok = (list, v) => typeof v === 'string' && allowed[list] && allowed[list].has(v);

let t = {}; let parseError = '';
try {
  const block = ($json.content || []).find(c => c.type === 'text');
  t = JSON.parse(block.text.replace(/```json|```/g, '').trim());
} catch (e) { parseError = 'Could not read Claude reply'; }

const notes = [];
const main = ok('sector', t.main_sector) ? t.main_sector : null;
if (t.main_sector && !main) notes.push('Sector not on list: ' + t.main_sector);
const secondary = (t.secondary_sectors || []).filter(s => ok('sector', s) && s !== main).slice(0, 2);
const focus = (t.focus_areas || []).filter(s => ok('focus_area', s)).slice(0, 2);
const type = ok('company_type', t.company_type) ? t.company_type : null;
const size = ok('size_band', t.size_band) ? t.size_band : null;
if (parseError) notes.push(parseError);
if (t.review_note) notes.push(String(t.review_note));

const confidence = ['high', 'medium', 'low'].includes(t.confidence) ? t.confidence : 'low';
const locs = Array.isArray(t.uk_locations) && t.uk_locations.length ? t.uk_locations : src.uk_locations_found;

return {
  id: src.id,
  name: (t.name && String(t.name).trim()) || src.current_name,
  description: t.description || null,
  main_sector: main,
  secondary_sectors: secondary,
  focus_areas: focus,
  company_type: type,
  size_band: size,
  uk_locations: (locs || []).map(String).slice(0, 15),
  hires_remote_uk: typeof t.hires_remote_uk === 'boolean' ? t.hires_remote_uk : !!src.any_remote,
  tag_version: 1,
  tag_confidence: confidence,
  needs_review: !main || confidence === 'low' || notes.length > 0,
  review_note: notes.join(' | ') || null,
  tagged_at: new Date().toISOString()
};
